# -*- coding: utf-8 -*-
"""프로젝트 30개의 장치 도해 조각 — 의료영상
   배치 규칙 : 윗줄 부품 ①②③ 은 y 56~150 · x 가 왼쪽/가운데/오른쪽 1/3 에, 아랫줄 ④⑤⑥ 은 y 156~198 · 같은 1/3 에 둔다.
   (라벨 ①②③ 은 위, ④⑤⑥ 은 아래 고정 칸이라 지시선이 짧아진다) + 지시선 목표점(tg). 라벨 ①~⑥ 은 JS(svgFig)가 고정 칸에 그린다.
   색 규약 : 장치 #475569/#94a3b8 · 빔·파동 #7dd3fc/#fbbf24 · 정답 #34d399 · 경고 #fb7185 · 치수 #a78bfa"""
import math
PF={}
def T(x,y,s,c='#cfe0f5',sz=11,anc=None,w=None):
    return '<text x="%g" y="%g" fill="%s" font-size="%g"%s%s>%s</text>'%(x,y,c,sz,(' text-anchor="%s"'%anc if anc else ''),(' font-weight="%s"'%w if w else ''),s)
def R(x,y,w,h,rx=4,f='#475569',s='#94a3b8',sw=1.3):
    return '<rect x="%g" y="%g" width="%g" height="%g" rx="%g" fill="%s" stroke="%s" stroke-width="%g"/>'%(x,y,w,h,rx,f,s,sw)
def C(cx,cy,r,f='none',s='#94a3b8',sw=1.3):
    return '<circle cx="%g" cy="%g" r="%g" fill="%s" stroke="%s" stroke-width="%g"/>'%(cx,cy,r,f,s,sw)
def E(cx,cy,rx,ry,f='none',s='#94a3b8',sw=1.3):
    return '<ellipse cx="%g" cy="%g" rx="%g" ry="%g" fill="%s" stroke="%s" stroke-width="%g"/>'%(cx,cy,rx,ry,f,s,sw)
def L(x1,y1,x2,y2,c='#94a3b8',w=1.2,dash=None):
    return '<path d="M%g %g L%g %g" stroke="%s" stroke-width="%g"%s/>'%(x1,y1,x2,y2,c,w,(' stroke-dasharray="%s"'%dash if dash else ''))
def P(d,c='#94a3b8',w=1.3,f='none',dash=None):
    return '<path d="%s" stroke="%s" stroke-width="%g" fill="%s"%s/>'%(d,c,w,f,(' stroke-dasharray="%s"'%dash if dash else ''))
def AR(x1,y1,x2,y2,c='#fbbf24',w=2):
    dx,dy=x2-x1,y2-y1; n=math.hypot(dx,dy) or 1; ux,uy=dx/n,dy/n
    return L(x1,y1,x2,y2,c,w)+'<path d="M%g %g L%g %g L%g %g Z" fill="%s"/>'%(x2,y2,x2-ux*9-uy*4.5,y2-uy*9+ux*4.5,x2-ux*9+uy*4.5,y2-uy*9-ux*4.5,c)
def reg(i,parts,tg): PF[i]=(''.join(parts),tg)
# ── 공용 아이콘 ──
def LED(x,y,c='#fbbf24'): return C(x,y,7,c,c,1)+''.join(L(x+9*math.cos(a),y+9*math.sin(a),x+14*math.cos(a),y+14*math.sin(a),c,1.2) for a in [i*math.pi/4 for i in range(8)])
def FILMS(x,y,n,w=8,h=44,col='#7dd3fc'): return ''.join(R(x+i*w*0.9,y,w,h,1,'rgba(125,211,252,.18)',col,1) for i in range(n))
def PHONE(x,y,lab=''): return R(x,y,26,46,5,'#1e293b','#94a3b8')+C(x+13,y+8,3,'#0f172a','#34d399',1)+(T(x+13,y+34,lab,'#34d399',9,'middle') if lab else '')
def USS(x,y): return R(x,y,64,28,3,'#1e293b','#94a3b8')+C(x+16,y+14,9,'#0f172a','#7dd3fc',1.3)+C(x+48,y+14,9,'#0f172a','#7dd3fc',1.3)
def ARD(x,y): return R(x,y,56,34,3,'#0f3d2e','#34d399',1.3)+R(x+18,y+10,18,14,2,'#0b1424','#94a3b8',1)
def SERVO(x,y): return R(x,y,30,22,3,'#475569','#94a3b8')+R(x+30,y+7,10,8,2,'#cbd5e1','#cbd5e1',1)
def LAPTOP(x,y,w=70,h=40): return R(x,y,w,h,3,'#0f172a','#94a3b8',1.3)+R(x-8,y+h,w+16,5,2,'#475569','#94a3b8',1)
def SPK(x,y): return R(x,y,20,24,3,'#475569','#94a3b8',1.3)+C(x+10,y+12,6,'#0f172a','#fbbf24',1.4)
def MIC(x,y): return R(x,y,10,18,5,'#475569','#94a3b8',1.3)+L(x+5,y+18,x+5,y+26,'#94a3b8',1.4)
def WAVES(cx,cy,n=3,r0=8,dr=7,col='#7dd3fc'): return ''.join('<path d="M%g %g A%g %g 0 0 1 %g %g" stroke="%s" stroke-width="1.5" fill="none" opacity="%g"/>'%(cx+(r0+dr*i)*0.7,cy-(r0+dr*i)*0.7,r0+dr*i,r0+dr*i,cx+(r0+dr*i)*0.7,cy+(r0+dr*i)*0.7,col,max(.25,.9-i*.2)) for i in range(n))
def GRID(x,y,w,h,n=6): return ''.join(L(x+i*w/n,y,x+i*w/n,y+h,'#5b7099',.8) for i in range(n+1))+''.join(L(x,y+i*h/n,x+w,y+i*h/n,'#5b7099',.8) for i in range(n+1))
def PLOT(x,y,w,h,pts=None,col='#38bdf8'):
    o=[L(x,y+h,x+w,y+h,'#5b7099',1.2),L(x,y,x,y+h,'#5b7099',1.2)]
    if pts: o.append(P('M'+' L'.join('%g %g'%(x+px*w,y+h-py*h) for px,py in pts),col,1.8))
    return ''.join(o)
def BARS(x,y,w,h,vals,cols):
    n=len(vals); bw=w/n-4
    return ''.join(R(x+i*(bw+4),y+h-v*h,bw,v*h,1,cols[i%len(cols)],'none',0) for i,v in enumerate(vals))+L(x,y+h,x+w,y+h,'#5b7099',1.2)
def HEAD(cx,cy,r=22,les=True):
    s=E(cx,cy,r*0.85,r,'rgba(56,189,248,.05)','#94a3b8',1.5)+E(cx,cy,r*0.72,r*0.87,'rgba(148,163,184,.14)','#cbd5e1',1.2)+E(cx-r*0.12,cy,r*0.07,r*0.35,'#0b1424','#5b7099',1)+E(cx+r*0.12,cy,r*0.07,r*0.35,'#0b1424','#5b7099',1)
    return s+(C(cx+r*0.35,cy+r*0.2,r*0.1,'#f1f5f9','#f1f5f9',1) if les else '')
def BODY(cx,cy,rx=40,ry=24,f='rgba(251,113,133,.14)'): return E(cx,cy,rx,ry,f,'#94a3b8',1.4)
def TT(x,y,w=70): return E(x+w/2,y,w/2,6,'#334155','#94a3b8',1.3)+R(x+w/2-4,y,8,14,1,'#334155','#94a3b8',1)
def SCREEN(x,y,w=60,h=36,col='#34d399'): return R(x,y,w,h,3,'#0f172a',col,1.3)
def DET(x,y,w=80,h=8): return R(x,y,w,h,2,'#34d399','#34d399',1)
def MAG(cx,cy,r=30): return C(cx,cy,r,'none','#94a3b8',3)+C(cx,cy,r*0.62,'#0b1424','#5b7099',1.4)
def LAB(x,y,s,c='#9db0cc',sz=10.5,anc='start'): return T(x,y,s,c,sz,anc)
def WARN(cx,cy,s=1.0): return P('M%g %g L%g %g L%g %g Z'%(cx,cy-12*s,cx-12*s,cy+10*s,cx+12*s,cy+10*s),'#fb7185',1.6,'rgba(251,113,133,.15)')+T(cx,cy+6*s,'!','#fb7185',13*s,'middle','700')

def BOX(x,y,w,h,s,c='#fbbf24'): return R(x,y,w,h,6,'#0b1424','#3d5480',1.2)+T(x+w/2,y+h/2+4,s,c,11,'middle','700')
EXP=[(i/10,1-0.9*(1-math.exp(-0.45*i))*1.0) for i in range(0,11)]
# ═════════ R&E R01 ~ R10 ═════════
reg('R01',[LED(60,100),AR(80,100,125,100,'#fbbf24',1.6), FILMS(290,70,5), PHONE(560,76,'lux'), BOX(30,160,170,34,'어두운 방 · 같은 거리'), PLOT(290,158,70,36,[(i/10,1-i/12) for i in range(11)]), BOX(540,160,110,34,'ln(E₀/E) 표','#34d399')],[[60,100],[320,92],[573,100],[115,177],[325,176],[595,177]])
